  "about.founder.p2": "Ман аз як ширкати бузурги технологӣ нестам ва дар дафтари корпоративӣ наменишинам. Ман як соҳиби хурди чакана ҳастам, мисли шумо. Ман панҷ мағозаи электрониро идора мекунам, ки ба китобҳо ва лавозимоти дастсози дӯстдорони китоб тахассус доранд.\nМисли бисёр фурӯшандагони мустақил, ман ба нуқтаи шикаст расидам, вақте ки кӯшиш мекардам захираи чанд ҷойро идора кунам, ISBN-ҳои ноширонро дар баробари SKU-ҳои дастсози худам пайгирӣ кунам ва фармоишҳои таъминкунандагонро бо ҷадвалҳои вазнин идора кунам. Вақте ки барномае барои кӯмак ҷустуҷӯ кардам, шаш варианти гуногунро санҷидам. Ҳар яке ё комилан нопурра буд, ё ба таври боварнакарданӣ печида буд, ё ғоратгарона буд — барои абзорҳои асосӣ моҳона садҳо доллар талаб мекарданд.",
  "about.founder.p3": "Аз соҳае, ки эҷодкорони мустақилро истисмор мекунад, ноумед шуда, қарор додам ҳалли худро созам. Ман Luminous StockHaven-ро аз зарурат сохтам, то тиҷорати худро тоза, самаранок ва бо оромии комили хотир пеш барам.",
  "about.founder.p4": "Ман қарор додам ин платформаро ба нархи ростқавлона ва дастрас ба мардум кушоям, зеро ҳар соҳиби тиҷорати хурд сазовори абзорҳоест, ки воқеан кор мекунанд, бе он ки даромадашро зери хатар гузорад. Мо мустақилона соҳибӣ дорем, ҷомеаи худро бо шиддат ҳимоя мекунем ва аз ҷониби як фурӯшанда барои фурӯшандагон сохта шудаем.",
