  "upgrade.pendingCheckoutIntro": "Ин фазои кории нав то интихоби обуна ба Essentials маҳдуд аст. Муштариёни нави ҳақдор метавонанд дар як ҳисоб як озмоиши {days}-рӯза гиранд.",
  "upgrade.intro": "Муштариёни нави ҳақдор метавонанд дар як ҳисоб як озмоиши {days}-рӯза гиранд, на як озмоиш барои ҳар нақша. Тағйир додан аз Essentials ба Business ҳеҷ гоҳ озмоиши ройгони дигарро оғоз намекунад. Шумо дар",
