  "upgrade.pastDueTitle": "Пардохт дер кардааст",
  "upgrade.pastDueBody": "Пардохти охирини шумо анҷом наёфт, бинобар ин ин обуна гузаштааст. Шумо аз рӯзи пардохти номуваффақ дар давоми 14 рӯз, то даме ки онро ислоҳ мекунед, истифодаи пурраро нигоҳ медоред. Агар ислоҳ нашавад, обуна бекор карда мешавад, фазои корӣ барои 15 рӯз танҳо барои дидан мешавад ва баъд ҳисоб ва ҳама маълумоти он ҳазф карда мешавад. Пардохт дар ҳар вақт пеш аз ҳазф ҳама чизро бармегардонад. Усули пардохти худро дар поён нав кунед. Агар кӯмак лозим бошад, ба ин суроға нависед:",
