  "upgrade.paymentUpdateFailed": "Навсозии пардохтро оғоз кардан мумкин нашуд.",
  "upgrade.perMonth": "/ моҳ",
  "upgrade.taxNote": "Илова бар андозҳои татбиқшаванда, агар бошанд. Провайдер бояд пеш аз тасдиқи пардохт маблағи дақиқи шуморо нишон диҳад.",
  "upgrade.startSubscription": "Оғози обуна",
