  "valuation.retailValue": "{value} чакана",
  "valuation.noRetailPrice": "нархи чакана нест",
  "valuation.footnote": "Арзиши хароҷот арзиши воҳиди ҷории ҳар маҳсулотро истифода мебарад, бинобар ин қабул бо нархи нав тамоми рафро аз нав арзёбӣ мекунад. Воҳидҳои нигоҳдошташуда ҳанӯз дар ин ҷо ҳисоб карда мешаванд — онҳо дар даст ҳастанд, танҳо ба фармоиш ваъда дода шудаанд. Пули гумшуда ҳеҷ гоҳ ҳамчун сифр баррасӣ намешавад; майдонро холӣ гузоред, то рақам маълум шавад.",
