  "print.subtitleFull": "Барчаспҳои сканшаванда, варақҳои захира, рӯйхатҳои интихоб, фармоишҳои харид, ҳисобномаҳои муштарӣ, қабулҳо ва ҳуҷҷатҳои бозгашт.",
