  "settings.delete.underReview": "Дархости нест кардани ҳисоби шумо дар баррасӣ аст.",
  "settings.deletion.checkError": "Ҳоло дархостҳои мавҷударо санҷидан мумкин нест. Шумо ҳанӯз метавонед кӯшиш кунед, ки дархостро пешниҳод кунед.",
  "settings.deletion.confirmError": "Мо дархости несткунии шуморо тасдиқ карда натавонистем. Лутфан аз нав кӯшиш кунед.",
  "settings.deletion.receivedDesc": "Ҳисоб ва маълумоти шумо нест карда нашудаанд.",
