  "settings.details.address": "Суроға",
  'settings.details.taxRate': 'Меъёри андози ман',
  'settings.details.taxRateHint': 'Як бор муқаррар кунед. Ҳар фармоиши нави фурӯш андозашро аз ин меъёр пур мекунад — андози фармоиши алоҳидаро ҳанӯз ҳам тағйир дода метавонед.',
  "settings.details.taxMode": "Чӣ тавр фармоишҳо андози худро мегиранд",
  "settings.details.taxModeFixed": "Меъёри собити ман",
  "settings.details.taxModeAutomatic": "Худкор — аз рӯи иёлати муштарӣ",
  "settings.details.taxModeHint": "Ҳолати собит меъёри шуморо дар ҳар фармоиши нав истифода мебарад. Ҳолати худкор андози фармоиши навро бо меъёри асосии иёлати муштарӣ пур мекунад, ба маҳзи он ки иёлат дар фармоиш бошад, ва агар иёлат иваз шавад, онро аз нав пур мекунад. Инҳо меъёрҳои асосии иёлатҳо ҳастанд — андозҳои маҳаллӣ метавонанд бештар илова кунанд. Фармоиши бе иёлат, ё аз берун аз ИМА, меъёри собити шуморо дар боло истифода мебарад.",
  'settings.details.gs1Prefix': "Пешванди ширкати GS1",
  'settings.details.gs1PrefixHint': "Танҳо агар аз GS1 иҷозатномаи пешванд дошта бошед. Як бор танзим кунед ва тавлидгари рамз дар шакли маҳсулот метавонад аз рақамҳои худи шумо рамзҳои ҳақиқии хурдафурӯшии UPC ва EAN созад — ҳар яке танҳо як бор истифода мешавад ва ҳеҷ гоҳ дубора не. Агар надошта бошед, холӣ гузоред; барнома ҳеҷ гоҳ пешванд намебофад.",
  'settings.details.gs1LearnMore': "Бо GS1 нав ҳастед? Агар шумо дар кишвари худ зиндагӣ кунед, барои маълумоти бештар пайванди онро истифода баред; агар шумо дар Иёлоти Муттаҳида зиндагӣ кунед, пайванди GS1 US-ро истифода баред.",
