  "settings.pastDue.body": "Пардохти охирини шумо анҷом наёфт. Шумо аз рӯзи пардохти номуваффақ дар давоми 14 рӯз, то даме ки онро ислоҳ мекунед, истифодаи пурраро нигоҳ медоред. Агар ислоҳ нашавад, обуна бекор карда мешавад, фазои корӣ барои 15 рӯз танҳо барои дидан мешавад ва баъд ҳисоб ва ҳама маълумоти он ҳазф карда мешавад. Пардохт дар ҳар вақт пеш аз ҳазф ҳама чизро бармегардонад. Агар намедонед чӣ кор кунед, бо дастгирӣ тавассути theluminousbookshop@outlook.com тамос гиред.",
