  "settings.software.application": "Барнома",
  "settings.software.description": "Luminous StockHaven барнома аст. Тафсилоти тиҷорати шумо дар ҷои дигари ин саҳифа аз они шумост.",
  "settings.software.fixedNote": "Ин арзишҳо собитанд ва барои ҳар тиҷорат якхела пайдо мешаванд. Тағйири номи тиҷорати шумо ё тағйир додани логотипи он ҳеҷ гоҳ номи барномаро тағйир намедиҳад.",
