  "workforce.unscheduledNote": "Имрӯз навбат ба нақша гирифта нашудааст, бинобар ин ин вақт берун аз ҷадвал қайд мешавад.",
  "workforce.inbox.help": "Рӯйдодҳои қайди вақт, ҷавобҳо ба рухсатӣ, вазифаҳо, варақаҳои музди меҳнат ва тағйироти ҷадвал барои дастаи шумо, аввал навтаринҳо.",
  "workforce.messages.back": "Ҳамаи сӯҳбатҳо",
  "workforce.messages.empty": "Ҳоло сӯҳбатҳо нестанд. Бо тугмаи боло яктоашро оғоз кунед.",
  "workforce.messages.emptyThread": "Ҳоло паёмҳо нестанд. Барои оғоз салом гӯед.",
  "workforce.messages.help": "Паёмҳои хусусии як ба як бо дастаи шумо — ҳеҷ барномаи дигар лозим нест. Танҳо ду нафаре, ки дар сӯҳбат ҳастанд, онро хонда метавонанд, инчунин соҳиби тиҷорат, ки мағозаашро назорат мекунад.",
  "workforce.messages.new": "Паёми нав",
  "workforce.messages.oversight": "Намоиши соҳиб",
  "workforce.messages.oversightNote": "Шумо ин сӯҳбатро хонда метавонед, зеро ин тиҷорат аз они шумост. Шумо ба он ҳамроҳ шуда наметавонед.",
  "workforce.messages.owner": "Соҳиби тиҷорат",
