  "print.shipFrom": "Аз",
  "print.recipientNameLabel": "Номи гиранда",
  "print.recipientAddressLabel": "Суроғаи гиранда",
  "print.senderAddressLabel": "Суроғаи шумо (фиристанда)",
  "print.shippingNote": "Агар фармоиш нишонаи фиристодан дошта бошад, он аз фармоиш пур мешавад. Он чизе ки дар ин ҷо менависед, як бор чоп мешавад ва ҳеҷ гоҳ захира намешавад.",
  "print.carrier.title": "Барчаспи интиқолдиҳандаи шумо",
  "print.carrier.desc": "Почтаро аз интиқолдиҳанда харед, чунон ки имрӯз мекунед — ин барнома ҳеҷ гоҳ почта намефурӯшад, бинобар ин нархе, ки шумо мепардозед, ҳамеша нархи худи интиқолдиҳанда аст. Файли барчаспро дар ин ҷо захира кунед ва он дар ин фармоиш абадӣ мемонад: сабти шумо, дар даст агар чизе рӯй диҳад.",
