  "print.carrier.tooLarge": "Он файл хеле калон аст — файли барчасп бояд камтар аз 2 МБ бошад.",
  "print.carrier.badType": "Он файл кор намекунад — барчаспи PDF, PNG ё JPG-ро интихоб кунед.",
  "print.carrier.failed": "Барчаспро захира карда натавонистанд. Ҳеҷ чиз тағйир наёфт — боз кӯшиш кунед.",
  "print.carrier.removeConfirm": "Барчаспи захирашудаи интиқолдиҳанда барои ин фармоиш хориҷ карда шавад? Файл аз барнома нест карда мешавад.",
  "print.carrier.pdfHint": "Ин барчасп PDF аст. Он бо андозаи ҳақиқии худ кушода мешавад — аз намоишгар чоп кунед ва он дақиқан 4×6 мебарояд.",
  "print.carrier.pickOrderFirst": "Дар боло фармоишеро интихоб кунед, сипас барчаспи интиқолдиҳандаи онро дар ин ҷо захира кунед.",
  'print.carrier.pickFirstTap': "Аввал аз боло як фармоишро интихоб кунед — сипас ин тугма тамғаи интиқолдиҳандаро дар он фармоиш сабт мекунад.",
  "print.style.title": "Услуби ҳуҷҷат",
  "print.style.desc": "Ҳуҷҷатҳои худро аз они худ кунед. Ин интихобҳо ҳисобнома-фактура, квитансия, варақаи борпеч, ҳуҷҷатҳои бозгашт, варақаҳои маҳсулот, варақаҳои ҳисоб ва рӯйхатҳои интихоби шуморо оро медиҳанд — ва барои тиҷорати шумо дар хотир нигоҳ дошта мешаванд.",
  "print.style.logoLabel": "Логотипи шумо",
