  "print.style.logoOff": "Ҳоло логотип нест. Дар Танзимот якеро илова кунед ва он дар болои ҳуҷҷатҳои шумо чоп мешавад.",
  "print.style.color": "Чоп бо ранг",
  "print.style.colorHint": "Фаъол: логотип, тасвирҳо ва чаҳорчӯбаи шумо бо ранг чоп мешаванд. Хомӯш: ҳама чиз бо сиёҳу сафеди тоза чоп мешавад, сиёҳӣ сарфа мешавад.",
