  "print.style.saveFailed": "Услубро захира карда натавонистанд. Ҳеҷ чиз тағйир наёфт — боз кӯшиш кунед.",
  "print.style.imageWidth": "Васеъии тасвир",
  "print.style.imageLength": "Дарозии тасвир",
  "print.style.imageSizeHint": "Васеъӣ ҳиссаи васеъии саҳифа аст, ки тасвир ишғол мекунад; дарозӣ баландии аз ҳама зиёди чоп аст. Барои андозаи маъмул қуттиро холӣ гузоред.",
  "print.printedAt": "Чоп шуд {date} соати {time}",
  "print.style.previewText": "Рӯбоҳи қаҳваранги тез аз болои саги танбал меҷаҳад. 1234567890",
  "training.lessons.owner-shipping-labels.step1": "Маркази чоп дар ҳар ду нақша услуби тамғаи интиқол дорад: фармоиши муштариро интихоб кунед ва тамғаи 4×6 бо ном ва суроғаи харидор ва тиҷорати шумо ҳамчун фиристанда чоп кунед.",
  "training.lessons.owner-shipping-labels.step2": "Тамға сафедтамға аст, мисли ҳар ҳуҷҷати муштарӣ: танҳо номи тиҷорати шуморо дорад — ҳаргиз номи ин барномаро не — то бастае аз мағозаи шумо чунон намояд, ки аз мағозаи шумо омадааст.",
  "training.lessons.owner-shipping-labels.step3": "Суроғаи муштарӣ то 90 рӯз пас аз фармоиши охирини ӯ бо фармоишҳояш нигоҳ дошта мешавад, ва нишона аз суроғаи захирашудаи фармоиш, вақте ки он мавҷуд аст, оғоз меёбад; суроғае, ки ҳангоми чоп барои нишонаи якдафъаина чоп карда мешавад, баргардонида захира намешавад. Ном то ҳол аз фармоиш пур мешавад, то нишона ба ҳуҷҷатҳо мувофиқат кунад.",
  "training.lessons.owner-shipping-labels.step4": "Тамға аз ҳамон чор пайвасти ҳама тамғаҳо чоп мешавад — Bluetooth, Wi-Fi, Ethernet ва USB — ва чопгари гармии 4×6 андозаи стандартии он аст.",
  "training.lessons.owner-shipping-labels.step5": "Ба ҷои он почтаро аз интиқолдиҳанда харидед? Дар ҳамин бахш шумо метавонед файли барчаспи интиқолдиҳандаро — PDF, PNG ё JPG — бор кунед ва он дар фармоиш абадӣ захира мемонад: сабти шумо, дар даст агар чизе рӯй диҳад. Он бо андозаи ҳақиқии 4×6 чоп мешавад. Барнома ҳеҷ гоҳ почта намефурӯшад, бинобар ин нархи интиқолдиҳанда ягона нарх аст — ва ҳамеша нархи дуруст.",
  "training.lessons.owner-shipping-labels.title": "Тамғаҳои интиқол барои фармоишҳои муштариён",
  "training.lessons.print-shipping-label.step1": "Вақте фармоиш барои фиристодан омода аст, Маркази чопро кушоед, услуби тамғаи интиқолро интихоб кунед ва сипас фармоиши муштариро интихоб кунед. Номи харидор аз фармоиш пур мешавад.",
  "training.lessons.print-shipping-label.step2": "Суроғаеро, ки баста ба он меравад, санҷед. Вақте ки фармоиш суроғаи муштариро дорад — то 90 рӯз пас аз фармоиши охиринаш нигоҳ дошта мешавад — он барои шумо пур мешавад; суроғае, ки шумо ҳангоми чоп чоп мекунед, баргардонида захира намешавад, бинобар ин пеш аз чоп рамзи почта ва сатри охиринро бодиққат санҷед.",
  "training.lessons.print-shipping-label.step3": "Номи тиҷорати шумо дар боло ҳамчун фиристанда чоп мешавад. Агар суроғаи шумо низ дар тамға бошад, онро дар қуттии суроғаи фиристанда нависед; агар намехоҳед намоён шавад, холӣ гузоред.",
  "training.lessons.print-shipping-label.step4": "Дар тамғаи 4×6 чоп кунед — чопгари гармии тамға интихоби маъмул аст — ё дар ҳама гуна чопгар бо тугмаи чопи браузер. Тамғаро ҳамвор ба баста часпонед, дар ҷое ки аз канор тах нашавад.",
  "training.lessons.print-shipping-label.step5": "Агар почта аз интиқолдиҳанда харида шуда бошад, ба ҷои он файли барчаспи онҳоро дар фармоиш захира кунед: PDF, PNG ё JPG-еро, ки интиқолдиҳанда ба шумо дод, дар бахши Барчаспи интиқолдиҳандаи шумо бор кунед. Он ҳамчун сабти шумо дар фармоиш мемонад ва бо андозаи ҳақиқии 4×6 чоп мешавад — ва барчаспи суроғаи худи барнома ҳамеша он ҷост, вақте ки шумо истифодаи онро афзалтар медонед.",
  "training.lessons.print-shipping-label.title": "Тамғаи интиқолро чоп кунед",
