  "profile.ownerDesc": "Акси шумо ва номие, ки дастаи шумо шуморо бо он мешиносад. Акси худи шумо фавран намоён мешавад — тасдиқ лозим нест.",
  "profile.memberDesc": "Пас аз он ки Соҳиб онро тасдиқ мекунад, акси шумо дар паҳлӯи номи шумо намоён мешавад. То он вақт, танҳо ҳарфҳои аввали номи шумо намоён мешаванд.",
