  "profile.nameHint": "Ин ном дар ҳама ҷо калимаи Соҳибро иваз мекунад — дар паҳлӯи акси шумо, дар Паёмҳо ва дар экранҳои дастаи шумо. Агар онро холӣ гузоред, шуморо Соҳиб меноманд.",
