  "plansLib.includes.profilePhotos": "Аксҳои профилӣ барои тамоми дастаи шумо, ки Соҳиб тасдиқ кардааст",
  "apiErrors.notFound.photoFound": "Акс ёфт нашуд.",
  "apiErrors.profileOwnerNameOnly": "Танҳо соҳиби тиҷорат метавонад номи Соҳибро таъин кунад.",
  "apiErrors.profilePhotosApproveOwnerOnly": "Танҳо соҳиби тиҷорат метавонад аксҳои дастаро тасдиқ кунад.",
  "apiErrors.profilePhotosNoneWaiting": "Он узви даста ҳеҷ аксе надорад, ки мунтазири тасдиқ бошад.",
  "apiErrors.profileOwnerNameTooLong": "Номи худро то 80 аломат ё камтар нигоҳ доред.",
  "training.lessons.your-profile-photo.title": "Акси профили шумо",
  "training.lessons.your-profile-photo.step1": "Акси шумо дар болои барнома дар паҳлӯи номи шумо, дар саҳифаи Кормандон ва дар паҳлӯи паёмҳои шумо намоён мешавад — пас аз он ки Соҳиб онро тасдиқ мекунад. То он вақт, танҳо ҳарфҳои аввали номи шумо намоён мешаванд.",
  "training.lessons.your-profile-photo.step2": "Танзимотро кушоед ва Акси профили худро ёбед. Акси худро интихоб кунед ва фиристед. Он барои тасдиқ ба Соҳиб меравад — ҳангоми интизорӣ он дар ҳеҷ ҷо намоён намешавад.",
  "training.lessons.your-profile-photo.step3": "Вақте ки Соҳиб онро тасдиқ мекунад, занги шумо садо медиҳад ва акси шумо намоён шудан мегирад. Агар он тасдиқ нашавад, акси дигареро интихоб кунед ва ҳамонро фиристед.",
  "training.lessons.your-profile-photo.step4": "Иваз кардани акси шумо низ ҳамин тавр кор мекунад: акси нав мунтазири тасдиқ мешавад, ва акси ҳозираи шумо то тасдиқ шудани акси нав дар ҷояш мемонад. Агар ивазкунӣ тасдиқ нашавад, акси дигари шумо назди шумо мемонад.",
  "training.lessons.owner-profile-photos.title": "Аксҳои профилӣ ва номи шумо",
  "training.lessons.owner-profile-photos.step1": "Акси ҳар кас дар болои барнома дар паҳлӯи номи онҳо, дар саҳифаи Кормандони шумо ва дар паҳлӯи паёмҳои онҳо намоён мешавад. То он даме, ки шумо тасдиқ накунед, акси узви даста дар ҳеҷ ҷо намоён намешавад — тасдиқ танҳо аз они шумост, ва ҳеҷ кас наметавонад акси худро худаш тасдиқ кунад.",
  "training.lessons.owner-profile-photos.step2": "Вақте ки касе акс мефиристад, занги шумо садо медиҳад. Барои дидани он саҳифаи Кормандонро кушоед, сипас Тасдиқ кунед ё Тасдиқ накунед-ро интихоб кунед. Агар шумо тасдиқ накунед, ба он шахс гуфта мешавад, ки акси дигареро интихоб кунад.",
  "training.lessons.owner-profile-photos.step3": "Агар шахс акси худро иваз кунад, акси нав ҳамин тавр мунтазири тасдиқи шумо мешавад. Ҳангоми интизорӣ акси ҳозираи онҳо дар ҷояш мемонад — ва агар шумо ивазкуниро тасдиқ накунед, он ҳамон тавр мемонад.",
  "training.lessons.owner-profile-photos.step4": "Акси худи шумо ба тасдиқ ниёз надорад: онро дар Танзимот, дар зери Акси профили шумо таъин кунед. Ҳамон корт номи шуморо низ дар бар мегирад — номие, ки шумо дар он ҷо таъин мекунед, дар ҳама ҷое, ки дастаи шумо мебинад, дар барнома ва дар Паёмҳо, калимаи Соҳибро иваз мекунад.",
  "payroll.dd.corrected": "Шакли ислоҳшуда",
  "payroll.dd.correctedDone": "Тафсилоти ислоҳшудаи шумо ба соҳиб фиристода шуд.",
  "payroll.dd.correctionNotice": "Соҳиб шакли шуморо ба шумо баргардонд, то шумо онро ислоҳ кунед. Ҳар рақамро санҷед, имзо кунед ва дубора фиристед.",
  "payroll.dd.correctionWaiting": "Баргардонида шуд — шакли ислоҳшудаи онҳо интизор аст",
  "payroll.dd.fixHelp": "Агар рақаме хато бошад, тафсилоти худро ислоҳ кунед ва шаклро дубора фиристед. Шакли нави имзошудаи шумо ҷои кӯҳнаро мегирад ва ба соҳиб хабар дода мешавад, ки он ислоҳ шудааст.",
  "payroll.dd.fixMistake": "Хаторо ислоҳ кунед",
  "payroll.dd.form.historyTitle": "Шаклҳои қаблан имзошуда",
  "payroll.dd.form.ownerOnlyNote": "Ин шаклро танҳо шумо, соҳиб, кушода метавонед. Он рақамҳои пурраи бонк ва имзои аъзоро нишон медиҳад.",
