  "payroll.dd.signHelp": "Номи худро нависед, сипас интихоб кунед, ки имзои шумо чӣ гуна менамояд. Ин имзои электронии шумост — он дар шакли интиқоли мустақими шумо маҳз ҳамон тавре ки дар ин ҷо нишон дода шудааст, гузошта мешавад.",
