  "payroll.profile.noAddress": "Ҳанӯз ягон суроғаи хона сабт нашудааст.",
  "payroll.profile.note": "Ин тафсилот барои музди меҳнат ва шаклҳои андози шумо истифода мешавад ва танҳо шумо онҳоро дар ин ҷо дида метавонед. Агар чизе тағйир хоҳад, аз соҳиб ё менеҷери худ пурсед — танҳо онҳо онҳоро нав карда метавонанд.",
  "payroll.profile.title": "Тафсилоти сабтшудаи шумо",
  "payroll.stubs.print": "Чоп / боргирӣ",
  "apiErrors.invalidValue.signYourForm": "Барои имзо кардани шакли интиқоли мустақими худ номи худро нависед.",
  "apiErrors.invalidValue.chooseSignatureStyle": "Услуби имзоро интихоб кунед.",
  "apiErrors.invalidValue.noDdDetailsYet": "Он аъзои даста ҳанӯз тафсилоти худро нафиристодааст.",
  "training.lessons.owner-dd-setup.step5": "Он чизе ки мерасад, шакли мӯҳршуда ва имзошуда аст: аз сатри он шахс дар Музди меҳнат шумо метавонед онро кушоед, то рақамҳои пурраро хонед, чоп кунед ё нусха захира кунед — шумо ҳеҷ гоҳ онро таҳрир карда наметавонед. Агар рақам хато намояд, шаклро баргардонед: худи шахс онро ислоҳ мекунад ва дубора имзо мекунад, шакли ислоҳшудаи ӯ ҷои кӯҳнаро мегирад ва шакли қаблӣ бо санаи ивазшавиаш дар сабт мемонад.",
  "payroll.profile.ownerNote": "Инҳо тафсилоти худи шумоанд, ки дар файл ҳастанд, аз ҳисоби шумо. Танҳо шумо метавонед онҳоро дар ин ҷо бинед — ва чун онҳо аз они шумоанд, ҳар вақт тағйир ёбанд, дар ин ҷо навсозӣ карда метавонед.",
