  "subscribe.foundingTesterNote": "Ин фазои корӣ Business-ро ҳамчун озмоишгари муассис дорад — барои ҳамеша ройгон. Ҳеҷ корт нест, ҳеҷ пардохт нест, ҳаргиз.",
