  "guide.title": "Дастури фармоиш",
  "guide.subtitle": "Барои ҳар як ҷузъе, ки пар дорад: пар минуси он чи дар даст ва аллакай дар фармоиш аст, то андозаи бастаи таъминкунанда боло яклухт карда, аз рӯи таъминкунанда гурӯҳбандӣ шудааст.",
  "guide.emptyTitle": "Ҳанӯз парҳо нестанд",
  "guide.emptyBody": "Барои ҷузъ пар муқаррар кунед — чӣ қадар бояд дар даст бошад — ва дастур ҳисоб мекунад, ки чӣ фармоиш додан лозим аст, аз рӯи ҳар як таъминкунанда.",
