  "nav.xstoreMessages": "Паёмҳо байни мағозаҳо",
  "plansLib.businessIncludes.xstoreMessages": "Паёмҳо байни мағозаҳо — тамоми дастаи шумо, дар ҳамаи корхонаҳо",
  "xstore.title": "Паёмҳо байни мағозаҳо",
  "xstore.help": "Ҳамаи одамон дар ин ҳисоб, дар ҳамаи корхонаҳои шумо, дар як паёмдони умумӣ. Ба ҳар кадоме аз онҳо дар ин ҷо паём фиристед — матнӣ ё овозӣ, бо нишонаҳои расонидан ва хондан. Паёмҳои дохили мағозаи шумо ҳамон тавр мемонанд, ки буданд.",
  "xstore.empty": "Ҳоло ягон сӯҳбат нест. Бо Паёми нав якеро оғоз кунед.",
  "xstore.noPeople": "Ҳоло каси дигаре нест, ки ба ӯ паём фиристед. Одамон дар ин ҷо пас аз он ки ба яке аз корхонаҳои шумо ҳамроҳ мешаванд ва ворид мешаванд, пайдо мешаванд.",
  "xstore.deliveredLabel": "Расонида шуд",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "Паёмҳо байни мағозаҳо қисми нақшаи «Бизнес» мебошанд.",
  "apiErrors.invalidValue.personNotPartAccount": "Он шахс қисми ин ҳисоб нест.",
  "training.lessons.owner-xstore-messages.title": "Паёмҳо байни мағозаҳои шумо, барои соҳибон",
  "training.lessons.owner-xstore-messages.step1": "Паёмҳо байни мағозаҳо паёмдони дуюм аст, ки аз Паёмҳо ҷудо аст. Паёмҳо барои мағозаест, ки шумо дар он истодаед; ин дар ба ҳамаи одамон дар ҳисоби шумо, дар ҳар корхонае, ки соҳиби он ҳастед, мерасад — то панҷто.",
  "training.lessons.owner-xstore-messages.step2": "Паёмҳо байни мағозаҳоро аз меню кушоед ва бо ҳар кас дар рӯйхат сӯҳбат оғоз кунед. Рӯйхат ҳар як узви дастаро дар ҳамаи корхонаҳои шумо, ки ворид шудааст, бо мағозаҳое, ки дар онҳо кор мекунад, нишон медиҳад.",
  "training.lessons.owner-xstore-messages.step3": "Аксҳо ҳамроҳ мераванд: ҳар шахс акси тасдиқшудаи профили худро нишон медиҳад, ё агар надошта бошад, ҳарфҳои аввали номи худро. Ҳар паём сана ва вақти фиристода шуданашро дорад.",
  "training.lessons.owner-xstore-messages.step4": "Дар зери паёмҳои худ шумо метавонед бинед, ки паём расид — Расонида шуд, ва вақте шахси дигар сӯҳбатро мекушояд — Хонда шуд. Ёддоштҳои овозӣ дар ин ҷо низ кор мекунанд, айнан мисли Паёмҳо.",
  "training.lessons.owner-xstore-messages.step5": "Сӯҳбатҳо дар ин ҷо танҳо барои ду шахсе, ки дар онҳо иштирок мекунанд, хусусӣ мебошанд. Назорати шумо бар Паёмҳои дохили мағоза ба мағозаҳои дигар дахл надорад.",
  "training.lessons.mgr-xstore-messages.title": "Паёмҳо байни мағозаҳои шумо, барои менеҷерон",
  "training.lessons.mgr-xstore-messages.step1": "Паёмҳо байни мағозаҳо ба ҳамаи одамон дар ин ҳисоб, дар ҳар корхона мерасад — на танҳо ба мағозае, ки шумо дар он истодаед. Он дар меню ҷойгир аст, аз Паёмҳо ҷудо.",
  "training.lessons.mgr-xstore-messages.step2": "Аз рӯйхат сӯҳбат оғоз кунед: ҳар узви даста, ки ворид шудааст, дар он ҷост, бо мағозаҳое, ки дар онҳо кор мекунад, дар паҳлӯи номаш.",
  "training.lessons.mgr-xstore-messages.step3": "Матн фиристед, ё ёддошти овозӣ сабт кунед. Пеш аз фиристодани ёддошти овозӣ, шумо метавонед онро гӯш кунед, партоед ё фиристед — ҳамон тавр ки дар Паёмҳо.",
  "training.lessons.mgr-xstore-messages.step4": "Паёмҳои шумо ҳангоми расидан Расонида шуд ва ҳангоми кушодани сӯҳбат аз ҷониби шахси дигар Хонда шуд нишон медиҳанд. Акси паҳлӯи ҳар ном акси тасдиқшудаи профили он шахс аст.",
  "training.lessons.staff-xstore-messages.title": "Паёмҳо байни мағозаҳои шумо",
  "training.lessons.staff-xstore-messages.step1": "Паёмҳо байни мағозаҳо ҷоест, ки шумо метавонед ба ҳар кас дар ин ҳисоб, дар ҳар кадом корхонаи соҳиб муроҷиат кунед — савол ба мағозаи дигар дигар набояд интизор шавад.",
  "training.lessons.staff-xstore-messages.step2": "Онро аз меню кушоед, шахсро интихоб кунед ва нависед. Агар шахси лозима дар рӯйхат набошад, ӯ ҳоло ворид нашудааст — ҳамин ки ворид шавад, пайдо мешавад.",
  "training.lessons.staff-xstore-messages.step3": "Шумо дар ин ҷо низ ёддоштҳои овозӣ фиристода метавонед: сабт кунед, гӯш кунед, сипас фиристед ё партоед. Ҳар паём сана ва вақти фиристода шуданашро нишон медиҳад.",
  "training.lessons.staff-xstore-messages.step4": "Вақте шумо паём мефиристед, он ҳангоми расидан Расонида шуд ва ҳангоми кушодани сӯҳбат аз ҷониби шахси дигар Хонда шуд нишон медиҳад. Сӯҳбат танҳо барои шумо ва шахси дигар хусусӣ аст.",
  "nav.invoices": "Ҳисобномаҳои таъминкунанда",
