  "variance.title": "Фарқият",
  "variance.subtitle": "Барои ҳар маҳсулот: он чизе, ки дорухатҳо мегӯянд, бояд аз раф мерафт, дар паҳлӯи хӯроки кормандон, партов ва ҳама чизи дигаре, ки берун рафт. Он чизе, ки бе шарҳ мемонад, фарқест, ки бояд рафта шарҳ дод.",
