  "storefronts.ebayDesc": "Мағозаи eBay-и худро як маротиба пайваст кунед. Вақте ки ашё дар eBay фурӯхта мешавад, шумораи он дар ин ҷо худкор кам мешавад ва фурӯш дар ҳаракатҳои шумо сабт мешавад — ҳамон тавре ки агар он скан карда бароварда шуда бошад. Фурӯш танҳо ба як самт ҷорӣ мешавад: аз eBay ба барнома.",
