  "storefronts.matchingIntro": "{count} ашёи фурӯхташуда ҳанӯз ба маҳсулот мувофиқ карда нашудааст. Ҳар яки онро ба маҳсулоти он пайваст кунед ва фурӯшҳои нигоҳдоштаи он худкор сабт мешаванд — ҳеҷ чиз гум намешавад, вақте ки он мунтазир аст.",
