  "storefronts.subtitle": "Мағозаи онлайнро як маротиба пайваст кунед ва фурӯши он захираи шуморо худкор нав мекунад.",
  "storefronts.title": "Пайвастҳои мағозаи онлайн",
  "training.lessons.owner-ebay-connect.step1": "Пайвастҳои мағозаи онлайнро (дар гурӯҳи Фурӯш) кушоед ва eBay-ро пайваст кунед-ро пахш кунед. Шумо дар саҳифаи худи eBay ворид мешавед — барнома ҳеҷ гоҳ пароли eBay-и шуморо намебинад.",
  "training.lessons.owner-ebay-connect.step2": "Як мағозаи eBay ба як тиҷорат пайваст мешавад — тиҷорате, ки он мағоза молҳои онро мефурӯшад. Агар шумо зиёда аз як тиҷоратро идора кунед, ҳар мағозаро ба тиҷорати худаш пайваст кунед.",
  "training.lessons.owner-ebay-connect.step3": "Ҷойеро интихоб кунед, ки захираи eBay-и шумо дар он ҷост, то фурӯш аз рафи дуруст кам шавад.",
  "training.lessons.owner-ebay-connect.step4": "Аз он вақт сар карда, фурӯшҳо худкор меоянд: вақте ки ашё дар eBay фурӯхта мешавад, шумораи он дар ин ҷо кам мешавад ва фурӯш дар Ҳаракатҳо бо рақами фармоиши eBay сабт мешавад. Ҳеҷ чиз барнамегардад — барнома ҳеҷ гоҳ рӯйхатҳои eBay-и шуморо тағйир намедиҳад.",
  "training.lessons.owner-ebay-connect.step5": "Фурӯш аз рӯи SKU, UPC ё ISBN мувофиқ меояд — кадоме аз ин се, ки дар рӯйхат бошад. Агар фурӯш мувофиқ омада натавонад, он дар зери 'Фурӯшҳое, ки ба мувофиқат ниёз доранд' дар саҳифаи Пайвастҳои мағозаи онлайн мунтазир мемонад: онро як маротиба ба маҳсулоти он пайваст кунед ва он фурӯш — ва фурӯшҳои ояндаи монанди он — худкор сабт мешаванд. 'Фурӯшро ҳоло санҷед' ҳама чизҳои охиринро мегирад ва Қатъ кунед пайвастро бозмедорад; фурӯшҳое, ки аллакай сабт шудаанд, мемонанд.",
